[MemoryDiagnoser]
[SimpleJob(RuntimeMoniker.Net80)]
[MinColumn, MaxColumn, MeanColumn, MedianColumn]
public class ApiPerformanceTests
{
    private readonly HttpClient _client;
    private readonly List<Guid> _userIds;

    public ApiPerformanceTests()
    {
        var factory = new CustomWebAppFactory();
        _client = factory.CreateClient();

        // Seed data
        using var scope = factory.Services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        _userIds = db.Users.Select(u => u.Id).Take(100).ToList();
    }

    [Params(1, 10, 100)]
    public int BatchSize { get; set; }

    [Benchmark]
    public async Task GetUsersBatch()
    {
        var tasks = _userIds.Take(BatchSize)
            .Select(id => _client.GetAsync($"/api/users/{id}"));
        await Task.WhenAll(tasks);
    }
}

